import{_ as o,o as n,c as s,ah as a}from"./chunks/framework.eLu1Yovf.js";const i="/projects/uHand_UNO/en/latest/assets/image4.Bi7Wy97x.png",r="/projects/uHand_UNO/en/latest/assets/image4.rAnfqrVV.jpeg",l="data:image/png;base64,",c="/projects/uHand_UNO/en/latest/assets/image7.CzJqcMWn.png",d="/projects/uHand_UNO/en/latest/assets/image8.BS7RYPyL.png",h="/projects/uHand_UNO/en/latest/assets/image9.CcrBTxvx.png",p="/projects/uHand_UNO/en/latest/assets/image10.C02imxCo.png",g="/projects/uHand_UNO/en/latest/assets/image11.Cpk_f7bq.png",e="/projects/uHand_UNO/en/latest/assets/image12.Cprshpom.png",m="/projects/uHand_UNO/en/latest/assets/image13.CID9cc74.png",u="/projects/uHand_UNO/en/latest/assets/image14.xgmfWlR3.png",_="/projects/uHand_UNO/en/latest/assets/image15.B4btBF2-.png",A="/projects/uHand_UNO/en/latest/assets/image16.Bf8F1LnT.png",b="/projects/uHand_UNO/en/latest/assets/image17.DhsAgMte.png",y="/projects/uHand_UNO/en/latest/assets/image18.BNaf3RbG.png",w="/projects/uHand_UNO/en/latest/assets/image19.C1YWNtli.png",f="/projects/uHand_UNO/en/latest/assets/image20.ByPDRyNX.png",C="/projects/uHand_UNO/en/latest/assets/image21.CeE1senI.png",U="/projects/uHand_UNO/en/latest/assets/image22.DdO12eMb.png",N=JSON.parse('{"title":"5. APP Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5.APP_Control.md","filePath":"docs/5.APP_Control.md"}'),P={name:"docs/5.APP_Control.md"};function I(x,t,B,q,H,O){return n(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="_5-app-control" tabindex="-1">5. APP Control <a class="header-anchor" href="#_5-app-control" aria-label="Permalink to &quot;5. APP Control&quot;">​</a></h1><h2 id="_5-1-app-installation" tabindex="-1">5.1 APP Installation <a class="header-anchor" href="#_5-1-app-installation" aria-label="Permalink to &quot;5.1 APP Installation&quot;">​</a></h2><p>iOS users: search <a href="https://apps.apple.com/us/app/wonderbot-robot/id1519146341" target="_blank" rel="noreferrer"><strong>Wonderbot</strong></a> in App Store and download it.</p><p>Android users: Click <a href="https://play.google.com/store/apps/details?id=com.Wonder.bot" target="_blank" rel="noreferrer">&quot;<strong>Wonderbot</strong>&quot;</a> or refer to the appendix to install it.</p><h2 id="_5-2-device-connection" tabindex="-1">5.2 Device Connection <a class="header-anchor" href="#_5-2-device-connection" aria-label="Permalink to &quot;5.2 Device Connection&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Please enable Bluetooth and location services in the phone settings before opening APP.</p></li><li><p>Please use the Bluetooth button in the APP to pair and connect with the device. Do not pair with the key in the phone settings.</p></li><li><p>Take Android APP as example in this lesson.</p></li></ul></section><p>Step 1: Make sure the Bluetooth module is installed correctly on the uHand UNO 6 channel knob expansion board by aligning pins one by one, as shown below:</p><img loading="lazy" height="600" width="1200" class="common_img" src="'+i+'" style="width:600px;"><p>Step 2: Turn on the power switches of the battery case and the expansion board. Press the K1 and K2 buttons on the expansion board at the same time, and release them until the RGB light turns to green. Then it can exit the neutral position mode. (If it does not exit, you can not control by the knob or app.)</p><img loading="lazy" class="common_img" src="'+r+'" style="width:600px;"><p>Step 3: Open the APP <strong>&quot;Wonderbot&quot;</strong>, and tap on the icon <img loading="lazy" height="78" width="87" src="'+l+'" style="width:50px;"> at the top left corner to select <strong>&quot;uHand&quot;</strong>.</p><img loading="lazy" height="640" width="1268" class="common_img" src="'+c+'" style="width:600px;"><p>Step 4: In uHand interface, tap on <img loading="lazy" height="97" width="87" src="'+d+'" style="width:50px;"> at the top right corner, and find <strong>&quot;Hiwonder&quot;</strong> in Bluetooth list. Click on the link.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the <strong>&quot;Hiwonder&quot;</strong> does not appear immediately after clicking on the Bluetooth icon, you can click &quot;<strong>Search again</strong>&quot; to search it again.</p></section><img loading="lazy" height="594" width="1279" class="common_img" src="'+h+'" style="width:600px;"><p>Step 5: After successfully connecting, the Bluetooth icon at the top right corner will switch to a steady mode, and the robotic hand will return to its neutral mode.</p><h2 id="_5-3-control-instruction" tabindex="-1">5.3 Control Instruction <a class="header-anchor" href="#_5-3-control-instruction" aria-label="Permalink to &quot;5.3 Control Instruction&quot;">​</a></h2><p>There are two control modes for the app. The default mode is the slider control mode, where you can drag the slider to control the rotation angle of each servo. And the other is the fingertip control mode. You can open and close the robot hand by pressing buttons.</p><h3 id="_5-3-1-slider-control" tabindex="-1">5.3.1 Slider Control <a class="header-anchor" href="#_5-3-1-slider-control" aria-label="Permalink to &quot;5.3.1 Slider Control&quot;">​</a></h3><p>The app interface consists of two parts as shown below:</p><img loading="lazy" height="635" width="1268" class="common_img" src="'+p+'"><p>①：Menu Bar</p><table class="docutils-nobg" style="text-align:center;" border="1"><tbody><tr><td><img loading="lazy" height="94" width="116" class="common_img" src="'+g+'"></td><td>Go back to the home screen to select the robot </td></tr><tr><td><img loading="lazy" height="94" width="116" class="common_img" src="'+e+'"></td><td>Switch to fingertip control mode</td></tr><tr><td><img loading="lazy" height="94" width="116" class="common_img" src="'+m+'"></td><td> Bluetooth connection </td></tr><tr><td><img loading="lazy" height="94" width="116" class="common_img" src="'+u+'"></td><td> More information </td></tr></tbody></table><p>②：Control Area</p><table class="docutils-nobg" style="text-align:center;" border="1"><colgroup><col style="width:50%;"><col style="width:50%;"></colgroup><tbody><tr><td><img loading="lazy" height="129" width="241" class="common_img" src="'+_+'" style="width:1.94306in;height:1.04028in;"></td><td>The control pan-tilt (No.6 servo) rotates from 0 ° to 180 °</td></tr><tr><td><img loading="lazy" height="272" width="96" class="common_img" src="'+A+'" style="width:0.90278in;height:2.55903in;"></td><td>Control the opening and closing of the robotic hand (No.1 ~ 5 servo), the angle range is 0 ~ 180 °</td></tr><tr><td><img loading="lazy" height="111" width="311" class="common_img" src="'+b+'" style="width:1.94375in;height:0.69375in;"></td><td><p>Control the opening of the hand, that is</p><p>the angle of No.1 ~ 5 servo should be 180 °</p></td></tr><tr><td><img loading="lazy" height="107" width="308" class="common_img" src="'+y+'" style="width:1.94097in;height:0.67431in;"></td><td>Control all servos back to neutral position</td></tr></tbody></table><h3 id="_5-3-2-fingertip-control" tabindex="-1">5.3.2 Fingertip Control <a class="header-anchor" href="#_5-3-2-fingertip-control" aria-label="Permalink to &quot;5.3.2 Fingertip Control&quot;">​</a></h3><p>(1) Click <img loading="lazy" height="94" width="116" src="'+e+'" style="width:60px;"> on the menu bar to switch the mode to fingertip control. The interface in fingertip control mode is shown below:</p><img loading="lazy" height="560" width="1117" class="common_img" src="'+w+'"><p>(2) In this mode, the pan-tilt returns to the neutral position, while all five fingers open. When press the button on the right side of the interface, the corresponding finger will be bent and closed.</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="987" width="800" src="'+f+'" style="width:480px;"><img loading="lazy" height="987" width="800" src="'+C+'" style="width:480px;"></p><p>(3) To switch back to slider control mode, you can click <img loading="lazy" height="94" width="84" src="'+U+'" style="width:50px;"> in the upper right corner.</p>',31)])])}const z=o(P,[["render",I]]);export{N as __pageData,z as default};
